//! ACME certificate orchestration.
//!
//! Ported from the retired Python certbot flow. Vreckan serves its web UI over TLS. By default
//! it uses a self-signed certificate (generated by `tls.rs`). When ACME is
//! enabled (via `VRECKAN_ACME_*` env vars or the admin Certificates page),
//! this module issues and renews real certificates using the **native acmex
//! client** (`acme.rs`) — the only issuance backend (the legacy certbot
//! Docker sidecar has been retired).
//!
//! The issued certificate (cert chain + private key + metadata) lives in the
//! config **database** as the source of truth and persists across restarts; a
//! best-effort mirror is also written to the app's `/data/acme` storage (the
//! `live/{primary}/` layout shared with the retired certbot flow) for
//! backward compatibility.

use std::sync::{Arc, Mutex};

use async_trait::async_trait;
use der::Decode;
use serde_json::Value;
use tracing::{info, warn};

use crate::state::AppState;

/// Where the app reads issued certificates from. A `static` (not a plain
/// `const`) so tests can point it at a temp tree — mirroring the Python test's
/// `monkeypatch.setattr(acme_orchestrator, "ACME_CERT_DIR", ...)`. `None` means "use the
/// default `/data/acme`".
pub static ACME_CERT_DIR: std::sync::RwLock<Option<String>> = std::sync::RwLock::new(None);
/// Where the app looks for a host-provided /etc/letsencrypt (checked first).
/// A `static` so tests can point it at a temp tree (mirrors the Python
/// `monkeypatch.setattr(acme_orchestrator, "ACME_HOST_CERT_DIR", ...)`).
/// `None` means "use the default `/etc/letsencrypt`".
pub static ACME_HOST_CERT_DIR: std::sync::RwLock<Option<String>> = std::sync::RwLock::new(None);

/// The effective app-side cert dir (test override or the default `/data/acme`).
pub fn app_cert_dir() -> String {
    ACME_CERT_DIR
        .read()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
        .unwrap_or_else(|| "/data/acme".to_string())
}
/// The effective host-side cert dir (test override or the default
/// `/etc/letsencrypt`).
pub fn host_cert_dir() -> String {
    ACME_HOST_CERT_DIR
        .read()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
        .unwrap_or_else(|| "/etc/letsencrypt".to_string())
}

/// The effective ACME configuration (DB-over-env-over-default), mirroring the
/// `_Cfg` object returned by Python's `effective_acme_config()`. Both the
/// startup path and the background renewal loop read from this so a value
/// edited on the admin Certificates page takes effect without a container
/// restart.
#[derive(Clone, Debug)]
pub struct AcmeConfig {
    pub acme_enabled: bool,
    pub acme_ca: String,
    pub acme_domains: String,
    pub acme_auth: String,
    pub acme_staging: bool,
    pub acme_cloudflare_email: String,
    pub acme_cloudflare_token: String,
    pub acme_auto_renew: bool,
    pub acme_renew_check_hours: i64,
    pub acme_renew_before_days: i64,
    pub acme_dns_provider: String,
    pub acme_cloudflare_zone_id: String,
    pub acme_dns_provider_config: String,
}

/// Build the *effective* ACME settings (``app_settings`` DB override → env →
/// default). Mirrors `effective_acme_config`.
pub async fn effective_acme_config(state: &AppState) -> AcmeConfig {
    let s = &state.settings;
    let db = &state.db;
    let acme_enabled = s.get_setting(db, "acme_enabled").await.as_bool().unwrap_or(false);
    let acme_ca = s.get_setting(db, "acme_ca").await.as_str().unwrap_or("").to_string();
    let acme_ca = if acme_ca.is_empty() { "letsencrypt".to_string() } else { acme_ca };
    let acme_domains = s.get_setting(db, "acme_domains").await.as_str().unwrap_or("").to_string();
    let acme_auth_raw = s.get_setting(db, "acme_auth").await.as_str().unwrap_or("").to_string();
    let acme_auth = if acme_auth_raw.is_empty() {
        "dns-cloudflare".to_string()
    } else {
        acme_auth_raw
    };
    let acme_staging = s.get_setting(db, "acme_staging").await.as_bool().unwrap_or(false);
    let acme_cloudflare_email = s
        .get_setting(db, "acme_cloudflare_email")
        .await
        .as_str()
        .unwrap_or("")
        .to_string();
    let acme_cloudflare_token = s
        .get_setting(db, "acme_cloudflare_token")
        .await
        .as_str()
        .unwrap_or("")
        .to_string();
    let acme_auto_renew = s.get_setting(db, "acme_auto_renew").await.as_bool().unwrap_or(false);
    let acme_renew_check_hours =
        s.get_setting(db, "acme_renew_check_hours")
            .await
            .as_i64()
            .unwrap_or(0);
    let acme_renew_before_days =
        s.get_setting(db, "acme_renew_before_days")
            .await
            .as_i64()
            .unwrap_or(0);
    let acme_dns_provider = s
        .get_setting(db, "acme_dns_provider")
        .await
        .as_str()
        .unwrap_or("")
        .to_string();
    let acme_dns_provider = if acme_dns_provider.is_empty() {
        "cloudflare".to_string()
    } else {
        acme_dns_provider
    };
    let acme_cloudflare_zone_id = s
        .get_setting(db, "acme_cloudflare_zone_id")
        .await
        .as_str()
        .unwrap_or("")
        .to_string();
    let acme_dns_provider_config = s
        .get_setting(db, "acme_dns_provider_config")
        .await
        .as_str()
        .unwrap_or("")
        .to_string();
    AcmeConfig {
        acme_enabled,
        acme_ca,
        acme_domains,
        acme_auth,
        acme_staging,
        acme_cloudflare_email,
        acme_cloudflare_token,
        acme_auto_renew,
        acme_renew_check_hours,
        acme_renew_before_days,
        acme_dns_provider,
        acme_cloudflare_zone_id,
        acme_dns_provider_config,
    }
}

/// Parse the `acme_dns_provider_config` JSON string into a `Value` (defaulting
/// to an empty object on any parse error).
fn provider_config_value(raw: &str) -> Value {
    if raw.trim().is_empty() {
        return serde_json::json!({});
    }
    serde_json::from_str::<Value>(raw).unwrap_or(serde_json::json!({}))
}

/// Build the ACME issuance arguments from an effective config, including the
/// DNS provider registry for the selected provider. Returns `Err` when the
/// provider could not be built (e.g. missing credentials).
async fn build_issue_args<'a>(cfg: &'a AcmeConfig) -> Result<crate::acme::IssueArgs<'a>, String> {
    let domains: Vec<String> = cfg
        .acme_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    let primary = domains.first().cloned().unwrap_or_default();
    let registry = crate::acme::build_provider_registry(&crate::acme::AcmeDnsConfig {
        provider: &cfg.acme_dns_provider,
        cloudflare_token: cfg.acme_cloudflare_token.clone(),
        cloudflare_zone_id: cfg.acme_cloudflare_zone_id.clone(),
        cloudflare_email: cfg.acme_cloudflare_email.clone(),
        domain: primary.clone(),
        provider_config: &provider_config_value(&cfg.acme_dns_provider_config),
    })
    .await?;
    Ok(crate::acme::IssueArgs {
        ca: &cfg.acme_ca,
        staging: cfg.acme_staging,
        email: &cfg.acme_cloudflare_email,
        auth: &cfg.acme_auth,
        provider: &cfg.acme_dns_provider,
        domains,
        registry,
    })
}

/// Test seam: replace the real `crate::acme::issue_certificate` call with a
/// scripted issuer so the suite never touches the network (mirrors the
/// Python test's fake client).
#[async_trait]
pub trait AcmeIssuer: Send + Sync {
    async fn issue(
        &self,
        args: &crate::acme::IssueArgs<'_>,
    ) -> crate::acme::AcmeIssueResult;
}

/// Process-wide override for the ACME issuer (`None` = real acmex client).
pub static FAKE_ACME_ISSUER: Mutex<Option<Arc<dyn AcmeIssuer>>> = Mutex::new(None);

fn primary_domain(domains: &[String]) -> &str {
    domains.first().map(|s| s.as_str()).unwrap_or("")
}

/// Return the cert/key paths for the given domains, or `None` if no
/// certificate is present. The host `/etc/letsencrypt` is checked first; the
/// app-side path (`/data/acme`) is the fallback. Mirrors `cert_paths`.
fn cert_paths(domains: &[String]) -> Option<(String, String, String)> {
    let primary = primary_domain(domains);
    if primary.is_empty() {
        return None;
    }
    let host = host_cert_dir();
    let app = app_cert_dir();
    for base in [host, app] {
        let cert = format!("{base}/live/{primary}/cert.pem");
        let key = format!("{base}/live/{primary}/privkey.pem");
        if std::path::Path::new(&cert).is_file() && std::path::Path::new(&key).is_file() {
            return Some((cert, key, base));
        }
    }
    None
}

/// Parse a PEM certificate (held in memory) and return its notAfter as a Unix
/// timestamp (seconds), or `None` if it cannot be parsed.
pub fn acme_cert_expiry_from_pem(pem: &str) -> Option<i64> {
    let mut reader = std::io::Cursor::new(pem.as_bytes());
    let cert = rustls_pemfile::certs(&mut reader).next()?.ok()?;
    let x509 = x509_cert::Certificate::from_der(cert.as_ref()).ok()?;
    let not_after = x509.tbs_certificate().validity().not_after;
    Some(not_after.to_unix_duration().as_secs() as i64)
}

/// Parse a PEM certificate on disk and return its notAfter as a Unix
/// timestamp (seconds), or `None` if it cannot be read/parsed.
pub fn cert_expiry(cert_path: &str) -> Option<i64> {
    let pem = std::fs::read(cert_path).ok()?;
    acme_cert_expiry_from_pem(&String::from_utf8_lossy(&pem))
}

/// A persisted ACME certificate record — the source of truth for the issued
/// bundle, stored in the config database.
#[derive(Clone, Debug)]
pub struct AcmeCertRecord {
    /// The full certificate chain PEM.
    pub cert_pem: String,
    /// The private key PEM.
    pub key_pem: String,
    /// The CA that issued the cert (`letsencrypt` / `zerossl` / `google`).
    pub ca: String,
    /// Comma-separated domains covered by the cert.
    pub domains: String,
    /// notAfter as a Unix timestamp (seconds), when parseable.
    pub expires: Option<i64>,
}

/// Read the persisted ACME cert record from the config DB. Returns `None` when
/// no certificate has been persisted yet. The DB is the source of truth.
pub async fn acme_cert_record(state: &AppState) -> Option<AcmeCertRecord> {
    let db = &state.db;
    let cert_pem = db
        .get_app_setting("VRECKAN_ACME_CERT_PEM")
        .await
        .ok()
        .flatten()?;
    if cert_pem.trim().is_empty() {
        return None;
    }
    let key_pem = db
        .get_app_setting("VRECKAN_ACME_KEY_PEM")
        .await
        .ok()
        .flatten()
        .unwrap_or_default();
    let ca = db
        .get_app_setting("VRECKAN_ACME_CERT_CA")
        .await
        .ok()
        .flatten()
        .unwrap_or_default();
    let domains = db
        .get_app_setting("VRECKAN_ACME_CERT_DOMAINS")
        .await
        .ok()
        .flatten()
        .unwrap_or_default();
    let expires = db
        .get_app_setting("VRECKAN_ACME_CERT_EXPIRES")
        .await
        .ok()
        .flatten()
        .and_then(|s| s.trim().parse::<i64>().ok());
    Some(AcmeCertRecord { cert_pem, key_pem, ca, domains, expires })
}

/// Persist an ACME cert record to the config DB (the source of truth). Uses the
/// existing `app_settings` store; a `None` expiry is stored as an empty string
/// and read back as `None`.
pub async fn acme_persist_cert(state: &AppState, rec: &AcmeCertRecord) {
    let db = &state.db;
    let _ = db.set_app_setting("VRECKAN_ACME_CERT_PEM", &rec.cert_pem).await;
    let _ = db.set_app_setting("VRECKAN_ACME_KEY_PEM", &rec.key_pem).await;
    let _ = db.set_app_setting("VRECKAN_ACME_CERT_CA", &rec.ca).await;
    let _ = db.set_app_setting("VRECKAN_ACME_CERT_DOMAINS", &rec.domains).await;
    let expires = rec.expires.map(|e| e.to_string()).unwrap_or_default();
    let _ = db.set_app_setting("VRECKAN_ACME_CERT_EXPIRES", &expires).await;
}

/// Swap the running TLS listener to serve the certificate currently persisted
/// in the config DB, without re-binding the socket or restarting the process.
///
/// The listener's [`RustlsConfig`](axum_server::tls_rustls::RustlsConfig) is an
/// `Arc<ArcSwap<ServerConfig>>`; `reload_from_pem` stores a fresh `ServerConfig`
/// and every *new* TLS handshake serves it. In-flight connections keep the
/// previous certificate until they close. The config DB is the source of truth:
/// the cert/key are read back from it here, not from memory or disk. Returns
/// `true` when a cert was read from the DB and the swap performed, `false` when
/// no listener is attached or no cert is persisted yet.
pub async fn reload_served_cert(state: &AppState) -> bool {
    let Some(config) = state.tls_config.clone() else {
        return false;
    };
    let Some(rec) = acme_cert_record(state).await else {
        return false;
    };
    if rec.cert_pem.trim().is_empty() || rec.key_pem.trim().is_empty() {
        return false;
    }
    match config
        .reload_from_pem(rec.cert_pem.as_bytes().to_vec(), rec.key_pem.as_bytes().to_vec())
        .await
    {
        Ok(()) => {
            info!("hot-reloaded the served TLS certificate from the config DB");
            true
        }
        Err(e) => {
            warn!("hot-reload of the served TLS certificate failed: {e}");
            false
        }
    }
}

/// Build the `cert_status` JSON body from a resolved expiry. `cert`/`key`
/// carry either the PEM content (DB source) or the on-disk path (disk
/// fallback); the `source` label tells the caller which.
fn status_json(source: &str, cert: &str, key: &str, exp: Option<i64>) -> Value {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let (days_remaining, valid) = match exp {
        Some(e) => (Some((e - now) / 86400), e > now),
        None => (None, false),
    };
    let expiry = exp.map(|e| {
        chrono::DateTime::from_timestamp(e, 0)
            .map(|dt| dt.to_rfc3339())
            .unwrap_or_default()
    });
    serde_json::json!({
        "present": true,
        "source": source,
        "cert": cert,
        "key": key,
        "expiry": expiry,
        "days_remaining": days_remaining,
        "valid": valid,
    })
}

/// Describe the current certificate for the given domains. The config DB is
/// the source of truth: a persisted record is returned first (cert / key as
/// PEM content, `source` = `"acme_db"`). When nothing is persisted yet, the
/// disk layout (`/etc/letsencrypt`, then `/data/acme`) is used as a migration
/// fallback (cert / key as on-disk paths, `source` = `"host"`/`"app"`).
/// Mirrors `cert_status`.
pub async fn cert_status(state: &AppState, domains: &[String]) -> Value {
    if let Some(rec) = acme_cert_record(state).await {
        if !rec.cert_pem.is_empty() {
            return status_json("acme_db", &rec.cert_pem, &rec.key_pem, rec.expires);
        }
    }
    match cert_paths(domains) {
        Some((cert, key, base)) => {
            let source = if base == host_cert_dir() { "host" } else { "app" };
            status_json(source, &cert, &key, cert_expiry(&cert))
        }
        None => serde_json::json!({
            "present": false,
            "source": null,
            "cert": null,
            "key": null,
            "expiry": null,
            "days_remaining": null,
            "valid": false,
        }),
    }
}

/// True when the cert should be renewed: it is present and expires within
/// `renew_before_days` days (or is already expired). Mirrors `needs_renewal`.
pub fn needs_renewal(days_remaining: Option<i64>, renew_before_days: i64) -> bool {
    match days_remaining {
        Some(d) => d <= renew_before_days,
        None => false,
    }
}

/// Startup: make sure a valid ACME certificate exists. Returns the cert
/// status dict plus an `issued` flag. When `force` is true (the admin
/// "Issue/Renew Now" button), a currently valid certificate is (re)issued
/// anyway; otherwise a valid cert short-circuits and nothing happens (the
/// original "button did nothing" complaint).
pub async fn ensure_acme_cert(state: &AppState, cfg: &AcmeConfig, force: bool) -> Value {
    let domains: Vec<String> = cfg
        .acme_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    if !cfg.acme_enabled {
        let mut result = cert_status(state, &domains).await;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(false));
        }
        return result;
    }
    if domains.is_empty() {
        warn!("ACME enabled but no domains configured (acme_domains).");
        let mut result = cert_status(state, &domains).await;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    let status = cert_status(state, &domains).await;
    if !force && status.get("valid").and_then(|v| v.as_bool()).unwrap_or(false) {
        info!(
            "ACME certificate valid until {} ({}d).",
            status.get("expiry").and_then(|v| v.as_str()).unwrap_or("?"),
            status.get("days_remaining").and_then(|v| v.as_i64()).unwrap_or(0)
        );
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("issued".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    run_acme_issue(state, cfg, &status).await
}

/// Native acmex issuance: build the issue args (including the DNS provider
/// registry), run the ACME order (or the test seam), persist the bundle to the
/// config DB, and report the outcome.
async fn run_acme_issue(state: &AppState, cfg: &AcmeConfig, status: &Value) -> Value {
    let domains: Vec<String> = cfg
        .acme_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    let args = match build_issue_args(cfg).await {
        Ok(a) => a,
        Err(e) => {
            warn!("acmex issuance not configured: {e}");
            let mut result = status.clone();
            if let Some(obj) = result.as_object_mut() {
                obj.insert("issued".into(), Value::Bool(false));
                obj.insert("enabled".into(), Value::Bool(true));
                obj.insert("error".into(), Value::String(e));
            }
            return result;
        }
    };
    // Extract the Arc first so the `MutexGuard` is dropped before the `.await`
    // (a guard held across an await makes the handler future non-`Send`).
    let issuer = FAKE_ACME_ISSUER
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone();
    let r = match issuer {
        Some(issuer) => issuer.issue(&args).await,
        None => crate::acme::issue_certificate(&args).await,
    };
    // Persist the issued bundle to the config DB (the source of truth) before
    // re-reading the status, so the read-back reflects the new cert.
    if r.ok {
        if let (Some(cert_pem), Some(key_pem)) = (r.cert_pem.as_ref(), r.key_pem.as_ref()) {
            acme_persist_cert(
                state,
                &AcmeCertRecord {
                    cert_pem: cert_pem.clone(),
                    key_pem: key_pem.clone(),
                    ca: cfg.acme_ca.clone(),
                    domains: cfg.acme_domains.clone(),
                    expires: acme_cert_expiry_from_pem(cert_pem),
                },
            )
            .await;
            // Hot-reload: serve the freshly issued cert from the running TLS
            // listener in place (no restart). No-op before the listener is
            // attached (the startup path) when `tls_config` is still `None`.
            let _ = reload_served_cert(state).await;
        }
    }
    let status = cert_status(state, &domains).await;
    let mut result = status;
    if let Some(obj) = result.as_object_mut() {
        obj.insert("issued".into(), Value::Bool(r.ok));
        obj.insert("enabled".into(), Value::Bool(true));
        if !r.logs.is_empty() {
            obj.insert("logs".into(), Value::String(r.logs));
        }
        if let Some(err) = r.error {
            obj.insert("error".into(), Value::String(err));
        }
    }
    result
}

/// Background renewal: renew the cert if it is within the renewal window.
pub async fn renew_acme_cert(state: &AppState, cfg: &AcmeConfig) -> Value {
    let domains: Vec<String> = cfg
        .acme_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    if !cfg.acme_enabled || domains.is_empty() {
        let mut result = cert_status(state, &domains).await;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("renewed".into(), Value::Bool(false));
            obj.insert("due".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(cfg.acme_enabled));
        }
        return result;
    }
    let status = cert_status(state, &domains).await;
    let due = needs_renewal(
        status.get("days_remaining").and_then(|v| v.as_i64()),
        cfg.acme_renew_before_days,
    );
    if !due {
        let mut result = status;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("renewed".into(), Value::Bool(false));
            obj.insert("due".into(), Value::Bool(false));
            obj.insert("enabled".into(), Value::Bool(true));
        }
        return result;
    }
    run_acme_renew(state, cfg, &status).await
}

/// Native acmex renewal: build the issue args and run the ACME order (or the
/// test seam), persist the bundle to the config DB, and report the outcome.
async fn run_acme_renew(state: &AppState, cfg: &AcmeConfig, status: &Value) -> Value {
    let domains: Vec<String> = cfg
        .acme_domains
        .split(',')
        .map(|d| d.trim().to_string())
        .filter(|d| !d.is_empty())
        .collect();
    let args = match build_issue_args(cfg).await {
        Ok(a) => a,
        Err(e) => {
            warn!("acmex renewal not configured: {e}");
            let mut result = status.clone();
            if let Some(obj) = result.as_object_mut() {
                obj.insert("renewed".into(), Value::Bool(false));
                obj.insert("due".into(), Value::Bool(true));
                obj.insert("enabled".into(), Value::Bool(true));
                obj.insert("error".into(), Value::String(e));
            }
            return result;
        }
    };
    // Extract the Arc first so the `MutexGuard` is dropped before the `.await`
    // (a guard held across an await makes the handler future non-`Send`).
    let issuer = FAKE_ACME_ISSUER
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone();
    let r = match issuer {
        Some(issuer) => issuer.issue(&args).await,
        None => crate::acme::issue_certificate(&args).await,
    };
    // Persist the renewed bundle to the config DB (the source of truth) before
    // re-reading the status, so the read-back reflects the renewed cert.
    if r.ok {
        if let (Some(cert_pem), Some(key_pem)) = (r.cert_pem.as_ref(), r.key_pem.as_ref()) {
            acme_persist_cert(
                state,
                &AcmeCertRecord {
                    cert_pem: cert_pem.clone(),
                    key_pem: key_pem.clone(),
                    ca: cfg.acme_ca.clone(),
                    domains: cfg.acme_domains.clone(),
                    expires: acme_cert_expiry_from_pem(cert_pem),
                },
            )
            .await;
            // Hot-reload: serve the renewed cert from the running TLS listener
            // in place (no restart), sourcing it from the config DB.
            let _ = reload_served_cert(state).await;
        }
    }
    let status = cert_status(state, &domains).await;
    let mut result = status;
    if let Some(obj) = result.as_object_mut() {
        obj.insert("renewed".into(), Value::Bool(r.ok));
        obj.insert("due".into(), Value::Bool(true));
        obj.insert("enabled".into(), Value::Bool(true));
        if !r.logs.is_empty() {
            obj.insert("logs".into(), Value::String(r.logs));
        }
        if let Some(err) = r.error {
            obj.insert("error".into(), Value::String(err));
        }
    }
    result
}

/// Periodically check the ACME certificate and renew it when it is within the
/// configured renewal window. The interval and window are read fresh on each
/// iteration (admin-editable), so changes take effect without a restart.
/// No-op when ACME is disabled or auto-renew is off. Mirrors
/// `background_acme_renewal_job` in `api`.
pub async fn background_acme_renewal_job(state: AppState) {
    loop {
        // Read the effective config fresh each iteration (admin-editable), so
        // changes take effect without a restart.
        let cfg = effective_acme_config(&state).await;
        if !(cfg.acme_enabled && cfg.acme_auto_renew) {
            tokio::time::sleep(std::time::Duration::from_secs(300)).await;
            continue;
        }
        let result = renew_acme_cert(&state, &cfg).await;
        if result.get("due").and_then(|v| v.as_bool()).unwrap_or(false) {
            info!(
                "ACME certificate renewal {} ({}d remaining).",
                if result.get("renewed").and_then(|v| v.as_bool()).unwrap_or(false) {
                    "succeeded"
                } else {
                    "failed"
                },
                result.get("days_remaining").and_then(|v| v.as_i64()).unwrap_or(0)
            );
        }
        tokio::time::sleep(std::time::Duration::from_secs(
            cfg.acme_renew_check_hours.saturating_mul(3600) as u64,
        ))
        .await;
    }
}
